package techguns.gametest;
import net.minecraft.gametest.framework.*;
import net.minecraft.core.BlockPos;
import net.minecraft.world.item.*;
import net.minecraftforge.gametest.*;
import techguns.*;
import techguns.machines.*;
@GameTestHolder(Techguns.MODID) @PrefixGameTestTemplate(false)
public final class GrindingGameTests {
    private static ProcessingMachine machine(GameTestHelper h){h.setBlock(1,1,1,TGMachines.BLOCKS.get(MachineKind.GRINDER).get());return (ProcessingMachine)h.getBlockEntity(new BlockPos(1,1,1));}
    private static int count(ProcessingMachine m,Item item){int count=0;for(int i=2;i<m.inventory.getSlots();i++)if(m.inventory.getStackInSlot(i).is(item))count+=m.inventory.getStackInSlot(i).getCount();return count;}
    @GameTest(template="empty") public static void weaponSalvageProducesAllOriginalMaterials(GameTestHelper h){var m=machine(h);m.inventory.setStackInSlot(0,TGuns.pistol.get().getDefaultInstance());m.setEnergy(500);m.tick();for(int i=0;i<100;i++)m.tick();h.assertTrue(count(m,TGItems.INGOT_OBSIDIAN_STEEL.get())==3&&count(m,TGItems.PLASTIC_SHEET.get())==1&&count(m,Items.IRON_INGOT)==2,"Pistol salvage retains all three source output material stacks");h.assertTrue(m.energy.getEnergyStored()==0&&m.inventory.getStackInSlot(0).isEmpty(),"Salvage uses one weapon and 500 FE");h.succeed();}
    @GameTest(template="empty") public static void probabilisticAmmoRecoveryIsRolledOnceAndSaved(GameTestHelper h){var m=machine(h);m.inventory.setStackInSlot(0,new ItemStack(TGItems.PISTOL_ROUNDS.get(),16));m.inventory.setStackInSlot(1,new ItemStack(TGItems.MACHINE_UPGRADE_STACK.get(),15));m.setEnergy(8000);m.tick();var saved=m.saveWithoutMetadata();var rolled=saved.getList("pendingMultiple",net.minecraft.nbt.Tag.TAG_COMPOUND).copy();var copy=new ProcessingMachine(m.getBlockPos(),m.getBlockState());copy.setLevel(h.getLevel());copy.load(saved);h.assertTrue(copy.saveWithoutMetadata().getList("pendingMultiple",net.minecraft.nbt.Tag.TAG_COMPOUND).equals(rolled),"Reload cannot reroll salvage probabilities");for(int i=0;i<100;i++)copy.tick();h.assertTrue(count(copy,TGItems.NUGGET_LEAD.get())==12&&count(copy,TGItems.NUGGET_COPPER.get())==24,"Source chance values above one also produce guaranteed extra recovery");h.assertTrue(count(copy,Items.GUNPOWDER)>=1&&count(copy,Items.GUNPOWDER)<=2,"One-twelfth powder recovery is rounded probabilistically across sixteen rounds");h.succeed();}
    @GameTest(template="empty") public static void blockedGrinderOutputDoesNotConsumeInput(GameTestHelper h){var m=machine(h);for(int i=2;i<m.inventory.getSlots();i++)m.inventory.setStackInSlot(i,new ItemStack(Items.DIRT,64));m.inventory.setStackInSlot(0,TGuns.pistol.get().getDefaultInstance());m.tick();h.assertTrue(!m.running()&&!m.inventory.getStackInSlot(0).isEmpty(),"A full output grid cannot consume a weapon or roll a transaction");h.succeed();}
    @GameTest(template="empty") public static void armorRecoveryDependsOnRemainingCondition(GameTestHelper h){var item=TGEquipment.ARMOR.get("t1_combat_chestplate").get();var full=item.getDefaultInstance();var worn=full.copy();worn.setDamageValue(worn.getMaxDamage()-1);int intact=GrindingRecipe.find(full).maximum(1).stream().mapToInt(ItemStack::getCount).sum(),broken=GrindingRecipe.find(worn).maximum(1).stream().mapToInt(ItemStack::getCount).sum();h.assertTrue(intact>broken&&broken>=0,"Armor salvage uses the source inverse-damage repair-material calculation");h.succeed();}
}
